import { describe, it, expect, before } from "@tp/test";
import { double } from "./main.js";

describe("Double", () => {
  before(() => console.log("Preparing Double tests"));

  it("doubles a positive number", () => {
    expect(double(3)).to.equal(6);
  });

  it("supports asynchronous tests", async () => {
    const value = await Promise.resolve(double(-2));
    expect(value).to.equal(-4);
  });

  it("checks an expected exception", () => {
    expect(() => { throw new TypeError("demonstration"); })
      .to.throw(TypeError, "demonstration");
  });

  it.skip("work in progress", () => {
    expect(double(3)).to.equal(7);
  });
});
